import groovy.json.*
import java.text.SimpleDateFormat
import java.util.TimeZone
import org.apache.nifi.processor.io.*

def flowFile = session.get()
if (!flowFile) return

// قراءة الداتا
def input = new StringBuilder()
session.read(flowFile, { inputStream ->
    input.append(new String(inputStream.bytes, "UTF-8"))
} as InputStreamCallback)

// تحويل إلى JSON
def json = new JsonSlurper().parseText(input.toString())

// تحويل rating_time من Unix إلى تاريخ ووقت
if (json.rating_time != null && json.rating_time instanceof Number) {
    long ts = (json.rating_time as Long) * 1000
    def sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss")
    sdf.setTimeZone(TimeZone.getTimeZone("Africa/Cairo"))
    json.rating_time = sdf.format(new Date(ts))
}

// تعديل tmdbId
if (json.tmdbId != null) {
    json.tmdbId = (json.tmdbId as String).replace(".0","")
}

// كتابة النتيجة
flowFile = session.write(flowFile, { outputStream ->
    outputStream.write(JsonOutput.toJson(json).getBytes("UTF-8"))
} as OutputStreamCallback)

session.transfer(flowFile, REL_SUCCESS)

import groovy.json.*
import java.text.SimpleDateFormat
import java.util.TimeZone
import org.apache.nifi.processor.io.*

def flowFile = session.get()
if (!flowFile) return

// قراءة الداتا
def input = new StringBuilder()
session.read(flowFile, { inputStream ->
    input.append(new String(inputStream.bytes, "UTF-8"))
} as InputStreamCallback)

// تحويل إلى JSON
def json = new JsonSlurper().parseText(input.toString())

// تحويل rating_time من Unix إذا كان رقم
if (json.rating_time != null) {
    try {
        // حاول تحوّله لرقم (لو كانت Unix timestamp)
        long ts = json.rating_time.toString().toLong() * 1000
        def sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss")
        sdf.setTimeZone(TimeZone.getTimeZone("Africa/Cairo"))
        json.rating_time = sdf.format(new Date(ts))
    } catch (Exception e) {
        // لو مش رقم (String جاهز)، سيبه زي ما هو
        json.rating_time = json.rating_time.toString()
    }
}

// تعديل tmdbId
if (json.tmdbId != null) {
    json.tmdbId = json.tmdbId.toString().replace(".0","")
}

// كتابة النتيجة
flowFile = session.write(flowFile, { outputStream ->
    outputStream.write(JsonOutput.toJson(json).getBytes("UTF-8"))
} as OutputStreamCallback)

session.transfer(flowFile, REL_SUCCESS)

def t = record.getValue("title")

// extract year
def year = null
def matcher = t =~ /\((\d{4})\)$/
if (matcher.find()) {
    year = matcher.group(1) as Integer
}

// extract title without year
def name = t.replaceAll(/\s*\(\d{4}\)$/, "")

record.setValue("title", name)
record.setValue("release_year", year)

return record
